import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array to efficiently manage membership checks.
    This design leverages optimal bit array size and hash functions based on expected items and
    false positive rate to minimize memory use while maintaining accuracy.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.default_seed = 0
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.bit_array_size = self._optimal_bit_array_size()
        self.num_hash_functions = self._optimal_num_hash_functions()
        self.bit_array = [0] * self.bit_array_size

    def _optimal_bit_array_size(self) -> int:
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_num_hash_functions(self) -> int:
        return max(1, round((self.bit_array_size / self.expected_items) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Create a hash for a given item using a specific seed."""
        hash_result = hashlib.md5((item + str(seed)).encode()).hexdigest()
        return int(hash_result, 16) % self.bit_array_size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for seed in range(self.num_hash_functions):
            index = self._hash(item, seed)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        for seed in range(self.num_hash_functions):
            index = self._hash(item, seed)
            if self.bit_array[index] == 0:
                return False
        return True

