import math

class BloomFilter:
    """
    A Bloom Filter implementation that optimally determines the size of the bit array and
    the number of hash functions based on expected items and the desired false positive rate.
    The design focuses on minimizing memory usage while providing an efficient lookup mechanism
    for membership testing.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0 or not (0 < false_positive_rate < 1):
            raise ValueError("Expected items must be positive and false positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.bit_array_size = self._optimal_bit_array_size()
        self.num_hash_functions = self._optimal_num_hash_functions()
        self.bit_array = [0] * self.bit_array_size

