        """Calculate the optimal size of the bit array."""
        size = (-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2)
        return math.ceil(size)

    def _optimal_num_hash_functions(self) -> int:
        """Calculate the optimal number of hash functions."""
        num_hashes = (self.bit_array_size / self.expected_items) * math.log(2)
        return max(1, math.ceil(num_hashes))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash for a given item and seed."""
        hash_result = hashlib.md5((item + str(seed)).encode()).hexdigest()
        return int(hash_result, 16) % self.bit_array_size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
